#include <bits/stdc++.h>
using namespace std;

vector<int> parent_, sz;
int find(int x) {
    while (x != parent_[x]) { parent_[x] = parent_[parent_[x]]; x = parent_[x]; }
    return x;
}

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    vector<pair<int, int>> edges(n - 1);
    for (auto &e : edges) { scanf("%d %d", &e.first, &e.second); e.first--; e.second--; }
    set<pair<int, int>> deleted;
    for (int i = 0; i < k; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        deleted.insert({u - 1, v - 1});
    }
    parent_.resize(n);
    iota(parent_.begin(), parent_.end(), 0);
    sz.assign(n, 1);
    // Union the endpoints of every edge that is kept.
    for (auto [a, b] : edges) {
        if (deleted.count({a, b})) continue;
        a = find(a); b = find(b);
        if (sz[a] < sz[b]) swap(a, b);
        parent_[b] = a;
        sz[a] += sz[b];
    }
    vector<int> result;
    for (int i = 0; i < n; i++) if (parent_[i] == i) result.push_back(sz[i]);
    sort(result.begin(), result.end());
    string out = to_string(result.size());
    for (int s : result) out += ' ' + to_string(s);
    puts(out.c_str());
}

import java.io.*;
import java.util.*;

public class Main {
    static int[] parent, size;

    static int find(int x) {
        while (x != parent[x]) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        st.nextToken();
        int k = (int) st.nval;
        int[] ea = new int[n - 1], eb = new int[n - 1];
        for (int i = 0; i < n - 1; i++) {
            st.nextToken(); ea[i] = (int) st.nval - 1;
            st.nextToken(); eb[i] = (int) st.nval - 1;
        }
        HashSet<Long> deleted = new HashSet<>();
        for (int i = 0; i < k; i++) {
            st.nextToken(); long u = (long) st.nval - 1;
            st.nextToken(); long v = (long) st.nval - 1;
            deleted.add(u * n + v);
        }
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        // Union the endpoints of every edge that is kept.
        for (int i = 0; i < n - 1; i++) {
            if (deleted.contains((long) ea[i] * n + eb[i])) continue;
            int a = find(ea[i]), b = find(eb[i]);
            if (size[a] < size[b]) { int t = a; a = b; b = t; }
            parent[b] = a;
            size[a] += size[b];
        }
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) if (parent[i] == i) result.add(size[i]);
        Collections.sort(result);
        StringBuilder sb = new StringBuilder().append(result.size());
        for (int s : result) sb.append(' ').append(s);
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n, k := nextInt(), nextInt()
	edges := make([][2]int, n-1)
	for i := range edges {
		edges[i] = [2]int{nextInt() - 1, nextInt() - 1}
	}
	deleted := make(map[[2]int]bool, k)
	for i := 0; i < k; i++ {
		deleted[[2]int{nextInt() - 1, nextInt() - 1}] = true
	}
	parent := make([]int, n)
	size := make([]int, n)
	for i := range parent {
		parent[i], size[i] = i, 1
	}
	find := func(x int) int {
		for x != parent[x] {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	// Union the endpoints of every edge that is kept.
	for _, e := range edges {
		if deleted[e] {
			continue
		}
		a, b := find(e[0]), find(e[1])
		if size[a] < size[b] {
			a, b = b, a
		}
		parent[b] = a
		size[a] += size[b]
	}
	var result []int
	for i := 0; i < n; i++ {
		if parent[i] == i {
			result = append(result, size[i])
		}
	}
	sort.Ints(result)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	out.WriteString(strconv.Itoa(len(result)))
	for _, s := range result {
		out.WriteString(" " + strconv.Itoa(s))
	}
	out.WriteString("\n")
}
